def validate_loan_redirect(url: str) -> str:
    """
    Return the redirect target for a loan request.
    The site's fallback target is '/'.
    """
    if not url:
        return '/'
    parsed = urlparse(url)
    if parsed.fragment:
        return urlunparse(parsed._replace(fragment=''))
    return url
